import httpRequest from "@/apis/axios-api";
import type { BotGame, BotGameView, BotAgent, BotAgentView, BotMatch, BotMatchView, BotMatchDetail, BotMatchDetailView, GenericGameData } from "@/types/bot";
import type { QueryParams } from "@/types/request.ts";
import { JudgeLanguage } from "./language";

export enum BotStatus {
  BotStatusInit = 0,
  BotStatusQueuing = 1,
  BotStatusCompiling = 2,
  BotStatusRunning = 3,
  BotStatusFinish = 4,
  BotStatusTLE = 5,
  BotStatusMLE = 6,
  BotStatusOLE = 7,
  BotStatusRE = 8,
  BotStatusCE = 9,
  BotStatusCLE = 10,
  BotStatusJudgeFail = 11,
  BotStatusUnknown = 12,
  BotStatusMax,
}

export function IsBotStatusRunning(status: BotStatus) {
  switch (status) {
    case BotStatus.BotStatusInit:
    case BotStatus.BotStatusQueuing:
    case BotStatus.BotStatusCompiling:
    case BotStatus.BotStatusRunning:
      return true;
    default:
      return false;
  }
}

// 对局相关函数
export function GetBotMatchList(gameKey?: string, page: number = 1, pageSize: number = 20) {
  let url = `/bot/match/list?page=${page}&page_size=${pageSize}`;
  if (gameKey) {
    url += `&game_key=${gameKey}`;
  }
  return httpRequest({
    url,
    method: "get",
  });
}

export function GetBotStatusStr(status: BotStatus): string {
  switch (status) {
    case BotStatus.BotStatusInit:
      return "初始化";
    case BotStatus.BotStatusQueuing:
      return "排队中";
    case BotStatus.BotStatusCompiling:
      return "编译中";
    case BotStatus.BotStatusRunning:
      return "运行中";
    case BotStatus.BotStatusFinish:
      return "完成";
    case BotStatus.BotStatusTLE:
      return "超时";
    case BotStatus.BotStatusMLE:
      return "内存超限";
    case BotStatus.BotStatusOLE:
      return "输出超限";
    case BotStatus.BotStatusRE:
      return "运行错误";
    case BotStatus.BotStatusCE:
      return "编译错误";
    case BotStatus.BotStatusCLE:
      return "编译环境错误";
    case BotStatus.BotStatusJudgeFail:
      return "评测失败";
    case BotStatus.BotStatusUnknown:
      return "未知状态";
    default:
      return "无效状态";
  }
}

export function GetBotStatusTheme(status: BotStatus): string {
  switch (status) {
    case BotStatus.BotStatusInit:
    case BotStatus.BotStatusQueuing:
    case BotStatus.BotStatusCompiling:
    case BotStatus.BotStatusRunning:
      return "warning";
    case BotStatus.BotStatusFinish:
      return "success";
    case BotStatus.BotStatusTLE:
    case BotStatus.BotStatusMLE:
    case BotStatus.BotStatusOLE:
    case BotStatus.BotStatusRE:
    case BotStatus.BotStatusCE:
    case BotStatus.BotStatusCLE:
    case BotStatus.BotStatusJudgeFail:
    case BotStatus.BotStatusUnknown:
      return "danger";
    default:
      return "default";
  }
}

export function ParseBotGame(item: BotGame): BotGameView {
  const result: BotGameView = {} as BotGameView;
  result.id = item.id;
  result.gameKey = item.game_key;
  result.title = item.title;
  result.introduction = item.introduction;
  result.description = item.description;
  result.judgeCode = item.judge_code;
  result.playerMin = item.player_min;
  result.playerMax = item.player_max;

  // 只处理可能存在的字段
  if (item.inserter != undefined) {
    result.inserter = item.inserter;
  }
  if (item.inserterNickname != undefined) {
    result.inserterNickname = item.inserterNickname;
  }
  if (item.inserterUsername != undefined) {
    result.inserterUsername = item.inserterUsername;
  }
  if (item.insert_time != undefined) {
    result.insertTime = new Date(item.insert_time).toLocaleString();
  }
  if (item.modifier != undefined) {
    result.modifier = item.modifier;
  }
  if (item.modifierNickname != undefined) {
    result.modifierNickname = item.modifierNickname;
  }
  if (item.modifierUsername != undefined) {
    result.modifierUsername = item.modifierUsername;
  }
  if (item.modify_time != undefined) {
    result.modifyTime = new Date(item.modify_time).toLocaleString();
  }
  return result;
}

export function ParseBotAgent(item: BotAgent): BotAgentView {
  const result: BotAgentView = {} as BotAgentView;
  result.id = item.id;
  result.name = item.name;
  result.version = item.version;
  result.inserter = item.inserter;
  result.inserterUsername = item.inserter_username;
  result.inserterNickname = item.inserter_nickname;
  result.inserterEmail = item.inserter_email;
  if (item.insert_time != undefined) {
    result.insertTime = new Date(item.insert_time).toLocaleString();
  }
  if (item.modify_time != undefined) {
    result.modifyTime = new Date(item.modify_time).toLocaleString();
  }
  result.language = item.language;
  result.code = item.code;
  result.rank = item.rank;

  // 添加游戏相关字段的处理
  result.gameId = item.game_id;
  result.gameKey = item.game_key;
  result.gameTitle = item.game_title;

  // 添加状态字段的处理
  result.status = item.status;

  return result;
}

export function ParseBotMatch(item: BotMatch): BotMatchView {
  const result: BotMatchView = {} as BotMatchView;
  result.id = item.id;
  result.gameKey = item.game_key;
  result.gameTitle = item.game_title;
  result.status = item.status;
  result.agents = item.agents;
  result.enableRank = item.enable_rank;
  result.ranks = item.ranks;
  if (item.insert_time != undefined) {
    result.insertTime = new Date(item.insert_time).toLocaleString();
  }
  return result;
}

// 解析对局详情数据
export function ParseBotMatchDetail(item: BotMatchDetail): BotMatchDetailView {
  const result: BotMatchDetailView = {} as BotMatchDetailView;
  result.id = item.id;
  result.gameId = item.game_id;
  result.bots = item.bots;
  result.status = item.status;
  result.message = item.message;
  result.inserter = item.inserter;
  result.judger = item.judger;
  result.gameKey = item.game_key;
  result.gameTitle = item.game_title;
  result.agents = item.agents;
  result.inserterUsername = item.inserter_username;
  result.inserterNickname = item.inserter_nickname;
  result.inserterEmail = item.inserter_email;

  // 解析 ranks 数据
  if (item.ranks != undefined) {
    result.ranks = item.ranks;
  }

  // 解析时间
  if (item.insert_time != undefined) {
    result.insertTime = new Date(item.insert_time).toLocaleString();
  }
  if (item.judge_time != undefined) {
    result.judgeTime = new Date(item.judge_time).toLocaleString();
  }

  // 解析 JSON 字符串
  try {
    result.infoData = item.info ? JSON.parse(item.info) : {};
  } catch (e) {
    console.error("Failed to parse info:", e);
    result.infoData = {};
  }

  try {
    result.paramData = item.param ? JSON.parse(item.param) : {};
  } catch (e) {
    console.error("Failed to parse param:", e);
    result.paramData = {};
  }

  return result;
}

// 将对局详情转换为通用游戏数据
export function ConvertToGenericGameData(detail: BotMatchDetailView): GenericGameData {
  return {
    id: `game-${detail.gameKey}-${detail.id}`,
    gameKey: detail.gameKey,
    gameTitle: detail.gameTitle,
    status: detail.status,
    infoData: detail.infoData,
    paramData: detail.paramData,
    agents: detail.agents,
    ranks: detail.ranks,
  };
}

