// 获取可用的agent列表
export function GetBotAgentList(id?: number,  name?: string, gameKey?: string, username?: string, page: number = 1, pageSize: number = 20) {
  const params: QueryParams = {};
  if (id != undefined) {
    params.id = String(id);
  }
  if (gameKey != undefined) {
    params.game_key = gameKey;
  }
  if (username != undefined) {
    params.username = username;
  }
  if (name != undefined) {
    params.name = name;
  }
  params.page = String(page);
  params.page_size = String(pageSize);
  return httpRequest({
    url: "/bot/agent/list" + "?" + new URLSearchParams(params).toString(),
    method: "get",
  });
}

